package com.lianxibu.site.service.jobs;

import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.sources.SourceDayRunClaimAdmissionService;
import com.lianxibu.site.service.jobs.ReportInputSnapshotService.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;

/** Every original news source, original P1/P2 lineage and native report leaves. No report write authority. */
public final class NewsDayReportComponentService {
    private static final long MAX_BYTES=32L*1024*1024;
    private record Locator(FrozenSourceStagePlan.Reference p1,SourceValueIntentReceiptService.Handoff handoff,FrozenSourceStagePlan.Reference p2,String context,Instant preparationCutoff,String missing){ }
    private record Bound(SourceDedupBarrier.Member member,SourceDayRunClaimAdmissionService.Prepared registered,Locator locator,SourceDayNewsValuePermitService.Captured permit,NewsSourceReportComponentService.Captured component){ }
    /** Locator facts from the complete actual original included P1 source; never a native capability by themselves. */
    public record DedupSource(FrozenSourceStagePlan.Reference reference,String sourceId,String runId,LocalDate day){@Override public String toString(){return "OriginalQualifiedNewsDedupSource[redacted]";}}
    public static final class Captured {
        private final Object issuer;private final LocalDate day;private final Instant cutoff;private final SourceDayCohortSealService.Sealed original;private final JdbcSourceDayDedupClosures.Archive archive;private final SourceDedupBarrier.Closure closure;private final List<Bound> bound;
        private final List<Candidate> candidates;private final List<GenerationFlowService.Dependency> dependencies;private final List<MissingInput> missing;private final Map<String,List<String>> targets;private final Set<String> emptySources;private final List<NewsSourceReportComponentService.EntityLeaf> entityLeaves;
        private Captured(Object issuer,LocalDate day,Instant cutoff,SourceDayCohortSealService.Sealed original,JdbcSourceDayDedupClosures.Archive archive,SourceDedupBarrier.Closure closure,List<Bound> bound,List<Candidate> candidates,List<GenerationFlowService.Dependency> dependencies,List<MissingInput> missing,Map<String,List<String>> targets,Set<String> emptySources){this.issuer=issuer;this.day=day;this.cutoff=cutoff;this.original=original;this.archive=archive;this.closure=closure;this.bound=List.copyOf(bound);this.candidates=List.copyOf(candidates);this.dependencies=List.copyOf(dependencies);this.missing=List.copyOf(missing);var copy=new LinkedHashMap<String,List<String>>();targets.forEach((id,refs)->copy.put(id,List.copyOf(refs)));this.targets=Map.copyOf(copy);this.emptySources=Set.copyOf(emptySources);var all=new TreeMap<String,NewsSourceReportComponentService.EntityLeaf>();for(var binding:this.bound)if(binding.component!=null)for(var leaf:binding.component.entityLeaves())if(all.putIfAbsent(leaf.itemId(),leaf)!=null)throw invalid();this.entityLeaves=List.copyOf(all.values());}
        /** Every actual original registered source component; no source Top5 truncation. */
        public List<NewsSourceReportComponentService.EntityLeaf> entityLeaves(){return entityLeaves;}
        public long originalByteSize(){long bytes=original.plan().bundleJson().getBytes(StandardCharsets.UTF_8).length;for(var binding:bound)if(binding.component!=null)bytes=Math.addExact(bytes,binding.component.originalByteSize());return bytes;}
        /** P2 may still be pending. Only an original INCLUDED P1 with its native full proof and first is listed. */
        public List<DedupSource> includedDedupPlans(){var result=new ArrayList<DedupSource>();if(closure==null)return List.of();for(var binding:bound)if(binding.member.inclusion()==SourceDedupBarrier.Inclusion.ENABLED&&binding.locator!=null&&binding.locator.p1()!=null){var entry=closure.entries().stream().filter(e->e.sourceId().equals(binding.member.sourceId())).findFirst().orElseThrow(NewsDayReportComponentService::invalid);if(entry.decision()==SourceDedupBarrier.Decision.INCLUDED)result.add(new DedupSource(binding.locator.p1(),binding.member.sourceId(),binding.member.runId(),day));}result.sort(Comparator.comparing(DedupSource::sourceId));return List.copyOf(result);}
        public LocalDate day(){return day;}public Instant cutoff(){return cutoff;}
        public CatalogDayReportComponentService.DirectoryRef directory(){return new CatalogDayReportComponentService.DirectoryRef(original.plan().directory().ownerId(),original.plan().bundleHash(),original.sealedAt());}
        public List<Candidate> candidates(){return candidates;}public List<GenerationFlowService.Dependency> dependencies(){return dependencies;}public List<MissingInput> missing(){return missing;}public Map<String,List<String>> referenceTargetsByEvidence(){return targets;}public Set<String> successfulEmptySources(){return emptySources;}
        public boolean completeSuccessfulEmpty(){return candidates.isEmpty()&&missing.isEmpty()&&bound.stream().allMatch(b->b.member.inclusion()!=SourceDedupBarrier.Inclusion.ENABLED||emptySources.contains(b.member.sourceId()));}
        @Override public String toString(){return "OriginalNewsDayReportComponent[redacted]";}
    }
    private final Object issuer=new Object();private final SourceDayCohortSealService cohorts;private final SourceDayNewsDedupBarrierService barriers;private final JdbcSourceDayDedupClosures archives;private final SourceDayRunClaimAdmissionService registrations;
    private final FrozenSourceStagePlanService plans;private final SourceDedupStageProofService p1Proofs;private final SourceDedupStageAvailabilityService p1Availability;private final SourceValueIntentReceiptService handoffs;private final SourceDayNewsValuePermitService permits;private final SourceValueReportCompletionService completions;private final NewsSourceReportComponentService components;private final TransactionTemplate reads;
    public NewsDayReportComponentService(SourceDayCohortSealService cohorts,SourceDayNewsDedupBarrierService barriers,JdbcSourceDayDedupClosures archives,SourceDayRunClaimAdmissionService registrations,FrozenSourceStagePlanService plans,SourceDedupStageProofService p1Proofs,SourceDedupStageAvailabilityService p1Availability,SourceValueIntentReceiptService handoffs,SourceDayNewsValuePermitService permits,SourceValueReportCompletionService completions,NewsSourceReportComponentService components,PlatformTransactionManager manager){this.cohorts=Objects.requireNonNull(cohorts);this.barriers=Objects.requireNonNull(barriers);this.archives=Objects.requireNonNull(archives);this.registrations=Objects.requireNonNull(registrations);this.plans=Objects.requireNonNull(plans);this.p1Proofs=Objects.requireNonNull(p1Proofs);this.p1Availability=Objects.requireNonNull(p1Availability);this.handoffs=Objects.requireNonNull(handoffs);this.permits=Objects.requireNonNull(permits);this.completions=Objects.requireNonNull(completions);this.components=Objects.requireNonNull(components);reads=new TransactionTemplate(Objects.requireNonNull(manager));reads.setReadOnly(true);reads.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);}
    public Captured capture(LocalDate day,Instant cutoff){
        outside();if(day==null||cutoff==null||cutoff.getNano()%1000!=0)throw invalid();var original=cohorts.find(day);if(original==null)return null;if(original.sealedAt().isAfter(cutoff))throw invalid();
        var closed=barriers.find(day);var archive=reads.execute(s->archives.read(day,"news_tech"));if((closed==null)!=(archive==null))throw invalid();var closure=closed==null?null:closed.closure();if(closed!=null&&(!closed.original().plan().bundleJson().equals(original.plan().bundleJson())||!closed.original().sealedAt().equals(original.sealedAt())||!closure.json().equals(archive.closureJson())))throw invalid();
        var bound=new ArrayList<Bound>();long bytes=original.plan().bundleJson().getBytes(StandardCharsets.UTF_8).length;
        for(var member:original.plan().cohort("news_tech").members()){
            SourceDayRunClaimAdmissionService.Prepared registered=null;Locator locator=null;SourceDayNewsValuePermitService.Captured permit=null;NewsSourceReportComponentService.Captured component=null;
            if(member.inclusion()==SourceDedupBarrier.Inclusion.ENABLED){registered=registrations.prepare(Set.of(day),Set.of(member.sourceId()));var ownRegistered=registered;locator=reads.execute(s->locate(day,cutoff,member,closure,ownRegistered));
                if(locator.p2()!=null&&locator.missing()==null){var context=CanonicalJson.parse(locator.context());permit=permits.captureExisting(context.get(FrozenSourceDayDedupDependency.FIELD),context.get(FrozenSourceDedupDependency.FIELD),locator.preparationCutoff());if(!permit.dependency().originalBatchEligible())throw invalid();component=components.capture(locator.p2(),cutoff);if(component!=null)bytes=Math.addExact(bytes,component.originalByteSize());}
            }
            if(bytes>MAX_BYTES)throw new GenerationFlowService.CapacityGuarded();bound.add(new Bound(member,registered,locator,permit,component));
        }
        var captured=new Captured(issuer,day,cutoff,original,archive,closure,bound,List.of(),List.of(),List.of(),Map.of(),Set.of());return reads.execute(s->combine(captured));
    }
    /** The complete original directory, original missing states and all current leaf qualifications share this RR. */
    public Captured verifyObserved(Captured captured){readonly();if(captured==null||captured.issuer!=issuer)throw invalid();var fresh=combine(captured);if(!fresh.candidates.equals(captured.candidates)||!fresh.dependencies.equals(captured.dependencies)||!fresh.missing.equals(captured.missing)||!fresh.targets.equals(captured.targets)||!fresh.emptySources.equals(captured.emptySources)||!fresh.entityLeaves.equals(captured.entityLeaves))throw invalid();return captured;}
    private Captured combine(Captured captured){
        readonly();cohorts.verifyObserved(captured.original);if(!Objects.equals(captured.archive,archives.read(captured.day,"news_tech")))throw invalid();
        var candidates=new ArrayList<Candidate>();var dependencies=new LinkedHashMap<String,GenerationFlowService.Dependency>();var missing=new ArrayList<MissingInput>();var targets=new LinkedHashMap<String,List<String>>();var empty=new HashSet<String>();var ids=new HashSet<String>();long bytes=captured.original.plan().bundleJson().getBytes(StandardCharsets.UTF_8).length;
        for(String source:captured.original.plan().unassignedSourceIds())missing.add(new MissingInput("source",source,captured.day,"category_unassigned"));
        for(var bound:captured.bound){var member=bound.member;if(member.inclusion()!=SourceDedupBarrier.Inclusion.ENABLED){if(member.inclusion()==SourceDedupBarrier.Inclusion.UNCONFIGURED)missing.add(new MissingInput("source",member.sourceId(),captured.day,"unconfigured"));continue;}
            var locator=locate(captured.day,captured.cutoff,member,captured.closure,bound.registered);if(!Objects.equals(locator,bound.locator))throw invalid();
            if(locator.missing()!=null){missing.add(new MissingInput("source",member.sourceId(),captured.day,locator.missing()));continue;}
            if(bound.permit==null||!permits.verifyObserved(bound.permit,locator.preparationCutoff()).originalBatchEligible())throw invalid();
            if(bound.component==null){if(completions.read(locator.p2(),captured.cutoff)!=null)throw invalid();missing.add(new MissingInput("source",member.sourceId(),captured.day,"value_not_completed_at_cutoff"));continue;}
            var component=components.verifyObserved(bound.component);if(!captured.day.equals(component.day())||!member.sourceId().equals(component.sourceId())||!member.runId().equals(component.runId())||!captured.cutoff.equals(component.cutoff())||!locator.p2().equals(component.reference()))throw invalid();bytes=Math.addExact(bytes,component.originalByteSize());if(bytes>MAX_BYTES)throw new GenerationFlowService.CapacityGuarded();
            for(var candidate:component.value().candidates()){if(!ids.add(candidate.evidence().id()))throw invalid();candidates.add(candidate);}for(var dependency:component.value().dependencies()){var previous=dependencies.putIfAbsent(dependency.id(),dependency);if(previous!=null&&!previous.equals(dependency))throw invalid();}
            for(var entry:component.referenceTargetsByEvidence().entrySet())if(targets.putIfAbsent(entry.getKey(),entry.getValue())!=null)throw invalid();missing.addAll(component.value().missing());if(component.successfulOriginalEmpty())empty.add(member.sourceId());
        }
        if(!ids.equals(targets.keySet()))throw invalid();return new Captured(issuer,captured.day,captured.cutoff,captured.original,captured.archive,captured.closure,captured.bound,candidates,List.copyOf(dependencies.values()),missing,targets,empty);
    }
    private Locator locate(LocalDate day,Instant cutoff,SourceDedupBarrier.Member member,SourceDedupBarrier.Closure closure,SourceDayRunClaimAdmissionService.Prepared registered){
        readonly();if(!registrations.allowsObserved(registered,member.runId()))return new Locator(null,null,null,null,null,"run_registration_unproven");
        if(closure==null||closure.observedAt().isAfter(cutoff))return new Locator(null,null,null,null,null,"day_dedup_unproven_at_cutoff");var entry=closure.entries().stream().filter(e->e.sourceId().equals(member.sourceId())).findFirst().orElseThrow(NewsDayReportComponentService::invalid);
        var address=CollectionIntentIdentity.create(member.sourceId(),"daily",day,1,"news_tech");var p1=plans.findImmutableReference(address.id(),address.logicalKey(),1,GenerationFlowService.Stage.NEWS_DEDUP,day);
        if(entry.progress()!=null){if(p1==null)throw invalid();var committed=p1Proofs.readCommitted(p1);if(committed==null)throw invalid();var proof=committed.proof();var body=CanonicalJson.parse(proof.json());var at=p1Availability.availableAt(proof,closure.observedAt());if(at==null||!at.equals(entry.progress().availableAt())||!proof.hash().equals(entry.progress().proofHash())||!member.runId().equals(WireValues.id(body.get("run_id"),false))||!member.sourceId().equals(WireValues.id(body.get("source_id"),true))||!day.equals(WireValues.businessDate(body.get("business_date")))||!address.logicalKey().equals(WireValues.text(body.get("logical_key")))||WireValues.nonnegativeInteger(body.get("generation"))!=1)throw invalid();}
        if(entry.decision()!=SourceDedupBarrier.Decision.INCLUDED)return new Locator(p1,null,null,null,null,"dedup_"+entry.reason());if(p1==null)throw invalid();var handoff=handoffs.read(p1.ownerId());if(handoff==null)return new Locator(p1,null,null,null,null,"value_handoff_unproven");
        if(!p1.equals(handoff.p1Ref())||!member.runId().equals(handoff.runId())||!member.sourceId().equals(handoff.sourceId())||!day.equals(handoff.day())||!entry.progress().proofHash().equals(handoff.p1ResultHash())||!entry.progress().availableAt().equals(handoff.observedAt()))throw invalid();
        var p2=plans.findImmutableReference(handoff.p2Owner(),handoff.p2Key(),handoff.p2Generation(),GenerationFlowService.Stage.NEWS_VALUE,day);if(p2==null)return new Locator(p1,handoff,null,null,null,"value_plan_unproven");var plan=plans.readImmutable(p2);var time=plan.scope().cutoff();String context=plan.scope().stageContextJson();if(time.isAfter(cutoff))return new Locator(p1,handoff,p2,context,time,"value_prepared_after_cutoff");if(context==null||!CanonicalJson.parse(context).has(FrozenSourceDayDedupDependency.FIELD))return new Locator(p1,handoff,p2,context,time,"value_day_dependency_unproven");return new Locator(p1,handoff,p2,context,time,null);
    }
    private static void readonly(){if(!TransactionSynchronizationManager.isActualTransactionActive()||!TransactionSynchronizationManager.isCurrentTransactionReadOnly()||!Integer.valueOf(TransactionDefinition.ISOLATION_REPEATABLE_READ).equals(TransactionSynchronizationManager.getCurrentTransactionIsolationLevel()))throw invalid();}
    private static void outside(){if(TransactionSynchronizationManager.isActualTransactionActive())throw invalid();}
    private static IllegalStateException invalid(){return new IllegalStateException("original whole news day report component unavailable");}
}
